const fs = require('node:fs').promises
const limit = 1 << 20
const a = await fs.open('/data/f', 'r+')
const b = await fs.open('/data/f', 'r+')
try {
  await a.write(Buffer.concat([Buffer.alloc(limit, '.'), Buffer.from('EOF')]))
  for (let i = 0; i < 96; i++) await a.write('x', 2 * i)
  await b.write('Y!', 190)
  await a.write('Z', limit + 5)
  const middle = await b.read(Buffer.alloc(6), 0, 6, 188)
  console.log(middle.buffer.subarray(0, middle.bytesRead).toString())
  const tail = await b.read(Buffer.alloc(16), 0, 16, limit - 1)
  console.log(tail.buffer.subarray(0, tail.bytesRead).toString('hex'))
  await b.sync()
  await a.sync()
} finally {
  await b.close()
  await a.close()
}
